CustomField.formula:
IF(
/* 1. Checagem Prioritária: Se estiver Finalizado, encerra imediatamente */
ISPICKVAL(Oportunidade__r.StageName, "Finalizado"), "Encerrado",

/* 2. Se não estiver finalizado, verifica as condições de "Ativo" */
IF(
ISPICKVAL(Oportunidade__r.Est_gio__c, "Pronto para Entregar") ||
(ISPICKVAL(Oportunidade__r.Est_gio__c, "") && ISPICKVAL(Oportunidade__r.StageName, "Aprovado")),
"Ativo",

/* 3. Caso contrário, avalia os demais status via CASE */
CASE(TEXT(Oportunidade__r.StageName),
  /* "Finalizado" já foi tratado no topo, mas pode manter aqui ou remover */
  "Aprovado", "Novo",
  "Proposta", "Novo",
  "Perdido", "Cancelado",
  "Projeto postergado", "Cancelado",
  "Reprovado", "Cancelado",
  ""
)


)
)
